examples.template:
Row(
    modifier = Modifier.semantics { contentDescription = {{label}} },
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    verticalAlignment = Alignment.CenterVertically,
) {
    MonarchTextField(
        value = query,
        onValueChange = { query = it },
        modifier = Modifier.weight(1f),
        label = {{search}},
        placeholder = {{search}},
        labelVisibility = MonarchTextFieldLabelVisibility.Hidden,
    )
    Row(
        modifier = Modifier.semantics { contentDescription = {{group.label}} },
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    ) {
        MonarchButton(text = {{group.items.0}}, onClick = {}, variant = MonarchButtonVariant.Secondary)
        MonarchButton(text = {{group.items.1}}, onClick = {}, variant = MonarchButtonVariant.Secondary)
    }
    MonarchButton(text = {{end}}, onClick = {}, variant = MonarchButtonVariant.Secondary)
}

